def gen(rng):
    def make(q, pbias, maxv):
        ops, size = [], 0
        for _ in range(q):
            r = rng.random()
            if size == 0 or r < pbias:
                if size == 0 and r >= pbias and rng.random() < 0.5:
                    ops.append('empty')
                else:
                    ops.append('push ' + str(rng.randint(1, maxv)))
                    size += 1
            else:
                k = rng.choice(['pop', 'peek', 'empty', 'pop'])
                ops.append(k)
                if k == 'pop':
                    size -= 1
        return str(len(ops)) + '\n' + '\n'.join(ops)
    tests = ['1\nempty', '2\npush 5\nempty', '3\npush 1000000000\npeek\npop',
             '7\npush 1\npush 2\npeek\npop\nempty\npop\nempty',
             '8\npush 5\npush 6\npop\npush 7\npush 8\npop\npop\npop']
    for _ in range(40):
        tests.append(make(rng.randint(1, 20), rng.choice([0.4, 0.5, 0.6, 0.7]), rng.choice([5, 100, 10**9])))
    Q = 50000
    tests.append(make(Q, 0.5, 10**9))
    tests.append(make(Q, 0.65, 10**9))
    tests.append('50000\n' + '\n'.join(['push ' + str(rng.randint(1, 10**9)) for _ in range(25000)] + ['pop'] * 25000))
    ops = []
    for i in range(Q // 2):
        ops.append('push ' + str(rng.randint(1, 10**9)))
        ops.append('peek' if i % 3 else 'pop')
    # keep sequence valid: after a pop the queue may be empty only if pushes outnumber pops (they do)
    tests.append(str(len(ops)) + '\n' + '\n'.join(ops))
    return tests

